-- ============================================================
-- Ghost Online Private Server — full database schema + seed
-- MySQL 5.7+ / 8.x / MariaDB
--
-- Usage:
--   mysql -u USER -p -e "CREATE DATABASE IF NOT EXISTS ghostonline CHARACTER SET latin1;"
--   mysql -u USER -p ghostonline < database/schema.sql
--
-- This is the single definitive SQL file. Import once; no extra seed scripts.
-- Includes:
--   - GM account admin / admin
--   - ~8684 monster spawns
--   - ~1483 cash shop items
--   - 10716 monster drop rules
--   - 10 NPC item prices
--   - friends / letters tables
-- ============================================================
SET NAMES latin1;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `accountid` int NOT NULL AUTO_INCREMENT,
  `username` varchar(32) NOT NULL,
  `password` varchar(64) NOT NULL,
  `pin` int NOT NULL DEFAULT 0,
  `gender` int NOT NULL DEFAULT 0,
  `gm` int NOT NULL DEFAULT 0,
  `game_points` int NOT NULL DEFAULT 10000,
  `gift_points` int NOT NULL DEFAULT 0,
  `bonus_points` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`accountid`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `characters`;
CREATE TABLE `characters` (
  `ID` int NOT NULL AUTO_INCREMENT,
  `name` varchar(12) DEFAULT NULL,
  `userid` int DEFAULT NULL,
  `level` tinyint unsigned DEFAULT 1,
  `job` smallint DEFAULT 0,
  `str` smallint DEFAULT 3,
  `dex` smallint DEFAULT 3,
  `vit` smallint DEFAULT 3,
  `intel` smallint DEFAULT 3,
  `p_str` smallint DEFAULT 0,
  `p_dex` smallint DEFAULT 0,
  `p_vit` smallint DEFAULT 0,
  `p_int` smallint DEFAULT 0,
  `honor` smallint DEFAULT 0,
  `cmp` smallint DEFAULT 50,
  `chp` smallint DEFAULT 50,
  `cmmp` smallint DEFAULT 50,
  `cmhp` smallint DEFAULT 50,
  `exp` int DEFAULT 0,
  `map` smallint DEFAULT 2,
  `region` smallint DEFAULT 6,
  `charX` smallint DEFAULT 400,
  `charY` smallint DEFAULT 1000,
  `site` tinyint DEFAULT 1,
  `money` int DEFAULT 0,
  `mexp` int DEFAULT 30,
  `soul` smallint DEFAULT 0,
  `def` smallint DEFAULT 0,
  `p_def` smallint DEFAULT 0,
  `maxdamphy` smallint DEFAULT 10,
  `mindamphy` smallint DEFAULT 10,
  `maxdamw` smallint DEFAULT 0,
  `mindamw` smallint DEFAULT 0,
  `st_point` smallint DEFAULT 0,
  `sk_point` smallint DEFAULT 0,
  `p_damphy` smallint DEFAULT 0,
  `maxsoul` smallint DEFAULT 20,
  `p_damw` smallint DEFAULT 0,
  `sex` tinyint DEFAULT 1,
  `job2` tinyint DEFAULT -1,
  `job3` tinyint DEFAULT -1,
  PRIMARY KEY (`ID`),
  KEY `userid` (`userid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `equip`;
CREATE TABLE `equip` (
  `equipid` int NOT NULL,
  `type` int DEFAULT NULL,
  `charid` int DEFAULT NULL,
  `pos1` smallint DEFAULT 0,
  `pos2` tinyint DEFAULT 0,
  `slot` tinyint DEFAULT 0,
  `p_10` tinyint DEFAULT 0,
  `p_9` tinyint DEFAULT 0,
  `p_8` tinyint DEFAULT 0,
  `p_7` tinyint DEFAULT 0,
  `p_6` tinyint DEFAULT 0,
  `p_5` tinyint DEFAULT 0,
  `p_4` tinyint DEFAULT 0,
  `p_3` tinyint DEFAULT 0,
  `p_2` tinyint DEFAULT 0,
  `p_1` tinyint DEFAULT 0,
  `soulperc` smallint DEFAULT 0,
  `iscash` smallint DEFAULT 0,
  `timeuse` int DEFAULT -1,
  `isspecial` smallint DEFAULT 0,
  PRIMARY KEY (`equipid`),
  KEY `charid_pos` (`charid`, `pos1`, `pos2`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `spend`;
CREATE TABLE `spend` (
  `spendid` int NOT NULL,
  `itemid` int DEFAULT NULL,
  `charid` int DEFAULT NULL,
  `pos1` smallint DEFAULT 0,
  `pos2` tinyint DEFAULT 0,
  `amount` smallint DEFAULT 0,
  `iscash` smallint DEFAULT 0,
  `timeuse` int DEFAULT -1,
  `isspecial` smallint DEFAULT 0,
  `per` smallint DEFAULT 0,
  PRIMARY KEY (`spendid`),
  KEY `charid` (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `other`;
CREATE TABLE `other` (
  `otherid` int NOT NULL,
  `type` int DEFAULT NULL,
  `charid` int DEFAULT NULL,
  `pos1` smallint DEFAULT 0,
  `pos2` tinyint DEFAULT 0,
  `amount` smallint DEFAULT 0,
  `iscash` smallint DEFAULT 0,
  `timeuse` int DEFAULT -1,
  `isspecial` smallint DEFAULT 0,
  PRIMARY KEY (`otherid`),
  KEY `charid` (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `items`;
CREATE TABLE `items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `itemid` int DEFAULT NULL,
  `charid` int DEFAULT NULL,
  `inv` tinyint DEFAULT NULL,
  `pos` smallint DEFAULT NULL,
  `amount` smallint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `charid` (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `keymap`;
CREATE TABLE `keymap` (
  `charid` int NOT NULL,
  `pos0` int DEFAULT 0, `pos1` int DEFAULT 0, `pos2` int DEFAULT 2564, `pos3` int DEFAULT 3076,
  `pos4` int DEFAULT 3332, `pos5` int DEFAULT 4612, `pos6` int DEFAULT 5380, `pos7` int DEFAULT 0,
  `pos8` int DEFAULT 0, `pos9` int DEFAULT 0, `pos10` int DEFAULT 0, `pos11` int DEFAULT 0,
  `pos12` int DEFAULT 0, `pos13` int DEFAULT 0, `pos14` int DEFAULT 0, `pos15` int DEFAULT 0,
  `pos16` int DEFAULT 2052, `pos17` int DEFAULT 1284, `pos18` int DEFAULT 4, `pos19` int DEFAULT 1028,
  `pos20` int DEFAULT 0, `pos21` int DEFAULT 0, `pos22` int DEFAULT 0, `pos23` int DEFAULT 260,
  `pos24` int DEFAULT 0, `pos25` int DEFAULT 4868, `pos26` int DEFAULT 3588, `pos27` int DEFAULT 3844,
  `pos28` int DEFAULT 0, `pos29` int DEFAULT 13317, `pos30` int DEFAULT 0, `pos31` int DEFAULT 516,
  `pos32` int DEFAULT 0, `pos33` int DEFAULT 0, `pos34` int DEFAULT 3456, `pos35` int DEFAULT 2820,
  `pos36` int DEFAULT 0, `pos37` int DEFAULT 772, `pos38` int DEFAULT 0, `pos39` int DEFAULT 5124,
  `pos40` int DEFAULT 4100, `pos41` int DEFAULT 0, `pos42` int DEFAULT 0, `pos43` int DEFAULT 2308,
  `pos44` int DEFAULT 12805, `pos45` int DEFAULT 13061, `pos46` int DEFAULT 1540, `pos47` int DEFAULT 0,
  `pos48` int DEFAULT 0, `pos49` int DEFAULT 0, `pos50` int DEFAULT 1796, `pos51` int DEFAULT 0,
  `pos52` int DEFAULT 0, `pos53` int DEFAULT 0, `pos54` int DEFAULT 0, `pos55` int DEFAULT 0,
  `pos56` int DEFAULT 13573, `pos57` int DEFAULT 0, `pos58` int DEFAULT 0, `pos59` int DEFAULT 25606,
  `pos60` int DEFAULT 25862, `pos61` int DEFAULT 26118, `pos62` int DEFAULT 26374, `pos63` int DEFAULT 26630,
  `pos64` int DEFAULT 26886, `pos65` int DEFAULT 27142, `pos66` int DEFAULT 0, `pos67` int DEFAULT 0,
  `pos68` int DEFAULT 0, `pos69` int DEFAULT 0, `pos70` int DEFAULT 0, `pos71` int DEFAULT 0,
  `pos72` int DEFAULT 0, `pos73` int DEFAULT 0, `pos74` int DEFAULT 0, `pos75` int DEFAULT 0,
