  `pos88` int DEFAULT 0, `pos89` int DEFAULT 0,
  `flavor` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `skills`;
CREATE TABLE `skills` (
  `id` int NOT NULL AUTO_INCREMENT,
  `charid` int DEFAULT NULL,
  `skillid` int DEFAULT NULL,
  `points` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `charid` (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `skill_hotkeys`;
CREATE TABLE `skill_hotkeys` (
  `id` int NOT NULL AUTO_INCREMENT,
  `charid` int NOT NULL,
  `keyname` varchar(16) NOT NULL,
  `skillid` int NOT NULL DEFAULT -1,
  `stype` smallint NOT NULL DEFAULT -1,
  `sslot` smallint NOT NULL DEFAULT -1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `char_key` (`charid`, `keyname`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `quests`;
CREATE TABLE `quests` (
  `id` int NOT NULL AUTO_INCREMENT,
  `charid` int NOT NULL,
  `questid` int NOT NULL,
  `state` int NOT NULL DEFAULT 0,
  `progress` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `char_quest` (`charid`, `questid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `cash_inven`;
CREATE TABLE `cash_inven` (
  `id` int NOT NULL AUTO_INCREMENT,
  `charid` int NOT NULL,
  `slot` tinyint NOT NULL DEFAULT 0,
  `itemid` int NOT NULL,
  `amount` smallint NOT NULL DEFAULT 1,
  `islocked` tinyint NOT NULL DEFAULT 1,
  `term` int NOT NULL DEFAULT -1,
  PRIMARY KEY (`id`),
  KEY `charid_slot` (`charid`, `slot`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `gifts`;
CREATE TABLE `gifts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(20) NOT NULL,
  `itemid` int NOT NULL,
  `itemname` varchar(62) DEFAULT '',
  `amount` smallint NOT NULL DEFAULT 1,
  `islocked` tinyint NOT NULL DEFAULT 1,
  `term` int NOT NULL DEFAULT -1,
  `receive` tinyint NOT NULL DEFAULT 0,
  `sender` varchar(20) DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `recv_name` (`name`, `receive`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `pets`;
CREATE TABLE `pets` (
  `id` int NOT NULL AUTO_INCREMENT,
  `cid` int NOT NULL,
  `itemId` int NOT NULL,
  `decorateId` int NOT NULL DEFAULT 0,
  `name` varchar(20) NOT NULL DEFAULT 'Pet',
  `level` int NOT NULL DEFAULT 1,
  `hp` int NOT NULL DEFAULT 100,
  `mp` int NOT NULL DEFAULT 100,
  `exp` int NOT NULL DEFAULT 0,
  `type` int NOT NULL DEFAULT 5,
  `slot` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `cid_type_slot` (`cid`, `type`, `slot`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `monster`;
CREATE TABLE `monster` (
  `id` int NOT NULL AUTO_INCREMENT,
  `monsterid` int DEFAULT NULL,
  `map` smallint DEFAULT NULL,
  `region` smallint DEFAULT NULL,
  `monsterX` smallint DEFAULT NULL,
  `monsterY` smallint DEFAULT NULL,
  `m_monsterid` smallint DEFAULT NULL,
  `health` int DEFAULT 0,
  `speed` float DEFAULT 3,
  `status` smallint DEFAULT 0,
  `damage_get` int DEFAULT 0,
  `hit_s` smallint DEFAULT 0,
  `side` smallint DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `map_region` (`map`, `region`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `cash_shop`;
CREATE TABLE `cash_shop` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category` tinyint NOT NULL,
  `item_id` int NOT NULL,
  `bargain` int NOT NULL DEFAULT 0,
  `term` int NOT NULL DEFAULT -1,
  `price` int NOT NULL DEFAULT 0,
  `flag` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `category` (`category`),
  KEY `item_id` (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `monster_drops`;
CREATE TABLE `monster_drops` (
  `id` int NOT NULL AUTO_INCREMENT,
  `monster_id` int NOT NULL,
  `kind` varchar(8) NOT NULL,
  `item_id` int NOT NULL,
  `min_qty` int NOT NULL DEFAULT 1,
  `max_qty` int NOT NULL DEFAULT 1,
  `chance_bps` int NOT NULL DEFAULT 0,
  `min_lv` int NOT NULL DEFAULT 1,
  `max_lv` int NOT NULL DEFAULT 100,
  PRIMARY KEY (`id`),
  KEY `monster_id` (`monster_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `item_prices`;
CREATE TABLE `item_prices` (
  `item_id` int NOT NULL,
  `price` int NOT NULL,
  PRIMARY KEY (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `friends`;
CREATE TABLE `friends` (
  `id` int NOT NULL AUTO_INCREMENT,
  `charid` int NOT NULL,
  `friendid` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `char_friend` (`charid`,`friendid`),
  KEY `friendid` (`friendid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DROP TABLE IF EXISTS `letters`;
CREATE TABLE `letters` (
  `id` int NOT NULL AUTO_INCREMENT,
  `to_charid` int NOT NULL,
  `from_name` varchar(20) NOT NULL,
  `body` varchar(512) NOT NULL DEFAULT '',
  `sent_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `unread` tinyint NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `to_charid_id` (`to_charid`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

SET FOREIGN_KEY_CHECKS = 1;

